#!/usr/bin/env python3
"""Offline DNS model-based regression workbench.

Reads one UTF-8 JSON document on stdin and writes one JSON document on stdout.

The document describes synthetic authoritative zones, resolver profiles,
candidate queries and observations.  The program builds a deterministic local
resolution model, adjudicates the observations against that model and selects
an exact minimum-cost diagnostic basis.
"""

import ipaddress
import json
import re
import sys

# ---------------------------------------------------------------- constants

INPUT_LIMIT = 8 * 1024 * 1024
MAX_DEPTH = 32

MAX_ZONES = 16
MAX_TOTAL_RECORDS = 1024
MAX_RRSET = 64
MAX_PROFILES = 8
MAX_MAX_ALIASES = 64
MAX_QUERIES = 20
MAX_COST = 1000
MIN_COST = 1
MAX_OBSERVATIONS = 64
MAX_ANSWER_RECORDS = 128
MAX_TXT = 256
MAX_LABEL = 63
MAX_WIRE = 255
MAX_ID = 32

TYPES = ('A', 'AAAA', 'TXT', 'CNAME')
RCODES = ('NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED')
WILDCARDS = ('rfc', 'off', 'one-label')
CNAME_MODES = ('follow', 'stop')

ID_RE = re.compile(r'[A-Za-z0-9_-]{1,32}')
LABEL_RE = re.compile(r'[A-Za-z0-9_-]{1,63}')
OCTET_RE = re.compile(r'0|[1-9][0-9]{0,2}')
NAME_CHARS = frozenset('abcdefghijklmnopqrstuvwxyz'
                       'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-')


class Invalid(Exception):
    """Raised for every rejected input."""


def fail():
    raise Invalid()


# ---------------------------------------------------------------- json input

def _pairs_hook(pairs):
    seen = set()
    for key, _value in pairs:
        if key in seen:
            fail()
        seen.add(key)
    return dict(pairs)


def _reject_constant(_name):
    fail()


def _depth_ok(node, limit=MAX_DEPTH):
    stack = [(node, 1)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, dict):
            if depth > limit:
                return False
            for value in item.values():
                stack.append((value, depth + 1))
        elif isinstance(item, list):
            if depth > limit:
                return False
            for value in item:
                stack.append((value, depth + 1))
    return True


def parse_document(raw):
    if not isinstance(raw, (bytes, bytearray)):
        fail()
    if len(raw) > INPUT_LIMIT:
        fail()
    try:
        text = bytes(raw).decode('utf-8')
    except UnicodeDecodeError:
        fail()
    try:
        doc = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_reject_constant)
    except Invalid:
        raise
    except (ValueError, RecursionError):
        fail()
    if not _depth_ok(doc):
        fail()
    return doc


# ---------------------------------------------------------------- primitives

def require_keys(obj, keys):
    if not isinstance(obj, dict):
        fail()
    if set(obj.keys()) != set(keys):
        fail()


def canon_name(value):
    """Validate and canonicalise an absolute domain name."""
    if type(value) is not str:
        fail()
    if value == '.':
        return '.'
    if not value.endswith('.'):
        fail()
    body = value[:-1]
    if body == '':
        fail()
    labels = body.split('.')
    wire = 1
    for label in labels:
        if label == '*':
            wire += 2
        elif LABEL_RE.fullmatch(label):
            wire += 1 + len(label)
        else:
            fail()
    if wire > MAX_WIRE:
        fail()
    return '.'.join(label.lower() for label in labels) + '.'


def canon_data(rtype, value):
    """Validate and canonicalise record data for the given type."""
    if type(value) is not str:
        fail()
    if rtype == 'A':
        parts = value.split('.')
        if len(parts) != 4:
            fail()
        for part in parts:
            if not OCTET_RE.fullmatch(part):
                fail()
            if int(part) > 255:
                fail()
        return value
    if rtype == 'AAAA':
        if '%' in value:
            fail()
        try:
            addr = ipaddress.IPv6Address(value)
        except ValueError:
            fail()
        return addr.compressed
    if rtype == 'TXT':
        if len(value) > MAX_TXT:
            fail()
        for char in value:
            code = ord(char)
            if code < 0x20 or code > 0x7E:
                fail()
        return value
    # CNAME
    return canon_name(value)


def canon_record(record):
    require_keys(record, ('owner', 'type', 'data'))
    rtype = record['type']
    if type(rtype) is not str or rtype not in TYPES:
        fail()
    owner = canon_name(record['owner'])
    data = canon_data(rtype, record['data'])
    return (owner, rtype, data)


def label_count(name):
    if name == '.':
        return 0
    return name.count('.')


def labels_of(name):
    if name == '.':
        return []
    return name[:-1].split('.')


def name_of_labels(labels):
    if not labels:
        return '.'
    return '.'.join(labels) + '.'


def parent_name(name):
    if name == '.':
        return '.'
    index = name.find('.')
    if index < 0:
        return '.'
    rest = name[index + 1:]
    return rest if rest else '.'


def at_or_below(name, origin):
    """True when name is the origin itself or a descendant of it."""
    if origin == '.':
        return True
    if name == origin:
        return True
    return name.endswith('.' + origin)


# ---------------------------------------------------------------- structures

def parse_zones(raw_zones):
    if not isinstance(raw_zones, list):
        fail()
    if len(raw_zones) > MAX_ZONES:
        fail()
    zones = []
    origins = set()
    total = 0
    for raw_zone in raw_zones:
        require_keys(raw_zone, ('origin', 'records'))
        origin = canon_name(raw_zone['origin'])
        if origin in origins:
            fail()
        origins.add(origin)
        raw_records = raw_zone['records']
        if not isinstance(raw_records, list):
            fail()
        total += len(raw_records)
        if total > MAX_TOTAL_RECORDS:
            fail()
        records = []
        for raw_record in raw_records:
            records.append(canon_record(raw_record))
        by_owner = {}
        for owner, rtype, data in records:
            if not at_or_below(owner, origin):
                fail()
            by_owner.setdefault(owner, {}).setdefault(rtype, set()).add(data)
        for owner, types in by_owner.items():
            for datas in types.values():
                if len(datas) > MAX_RRSET:
                    fail()
            if 'CNAME' in types:
                if len(types['CNAME']) != 1:
                    fail()
                if len(types) != 1:
                    fail()
                if owner == origin:
                    fail()
        existing = set()
        existing.add(origin)
        record_map = {}
        for owner, types in by_owner.items():
            existing.add(owner)
            cursor = owner
            while cursor != origin:
                cursor = parent_name(cursor)
                existing.add(cursor)
            for rtype, datas in types.items():
                record_map.setdefault(owner, {})[rtype] = sorted(datas)
        zones.append({'origin': origin, 'records': record_map, 'existing': existing})
    return zones


def parse_profiles(raw_profiles):
    if not isinstance(raw_profiles, list):
        fail()
    if len(raw_profiles) < 1 or len(raw_profiles) > MAX_PROFILES:
        fail()
    profiles = []
    seen = set()
    for raw_profile in raw_profiles:
        require_keys(raw_profile, ('id', 'max_aliases', 'cname', 'wildcard'))
        pid = raw_profile['id']
        if type(pid) is not str or not ID_RE.fullmatch(pid):
            fail()
        if pid in seen:
            fail()
        seen.add(pid)
        max_aliases = raw_profile['max_aliases']
        if type(max_aliases) is not int or max_aliases < 0 or max_aliases > MAX_MAX_ALIASES:
            fail()
        cname = raw_profile['cname']
        if type(cname) is not str or cname not in CNAME_MODES:
            fail()
        wildcard = raw_profile['wildcard']
        if type(wildcard) is not str or wildcard not in WILDCARDS:
            fail()
        profiles.append({'id': pid, 'max_aliases': max_aliases,
                         'cname': cname, 'wildcard': wildcard})
    return profiles


def parse_queries(raw_queries):
    if not isinstance(raw_queries, list):
        fail()
    if len(raw_queries) > MAX_QUERIES:
        fail()
    queries = []
    seen = set()
    for raw_query in raw_queries:
        require_keys(raw_query, ('id', 'name', 'type', 'cost'))
        qid = raw_query['id']
        if type(qid) is not str or not ID_RE.fullmatch(qid):
            fail()
        if qid in seen:
            fail()
        seen.add(qid)
        name = canon_name(raw_query['name'])
        qtype = raw_query['type']
        if type(qtype) is not str or qtype not in TYPES:
            fail()
        cost = raw_query['cost']
        if type(cost) is not int or cost < MIN_COST or cost > MAX_COST:
            fail()
        queries.append({'id': qid, 'name': name, 'type': qtype, 'cost': cost})
    return queries


def parse_observations(raw_observations, query_ids, profile_ids):
    if not isinstance(raw_observations, list):
        fail()
    if len(raw_observations) > MAX_OBSERVATIONS:
        fail()
    observations = []
    seen = set()
    for raw_obs in raw_observations:
        require_keys(raw_obs, ('id', 'query', 'profile', 'result'))
        oid = raw_obs['id']
        if type(oid) is not str or not ID_RE.fullmatch(oid):
            fail()
        if oid in seen:
            fail()
        seen.add(oid)
        qid = raw_obs['query']
        pid = raw_obs['profile']
        if type(qid) is not str or qid not in query_ids:
            fail()
        if type(pid) is not str or pid not in profile_ids:
            fail()
        result = raw_obs['result']
        if not isinstance(result, dict):
            fail()
        status = result.get('status')
        if status == 'timeout':
            require_keys(result, ('status',))
            parsed = {'status': 'timeout'}
        elif status == 'response':
            require_keys(result, ('status', 'rcode', 'answer'))
            rcode = result['rcode']
            if type(rcode) is not str or rcode not in RCODES:
                fail()
            raw_answer = result['answer']
            if not isinstance(raw_answer, list):
                fail()
            if len(raw_answer) > MAX_ANSWER_RECORDS:
                fail()
            answer = []
            for raw_record in raw_answer:
                answer.append(canon_record(raw_record))
            parsed = {'status': 'response', 'rcode': rcode, 'answer': answer}
        else:
            fail()
        observations.append({'id': oid, 'query': qid, 'profile': pid,
                              'result': parsed})
    return observations


# ---------------------------------------------------------------- model

def select_zone(name, zones):
    best = None
    best_depth = -1
    for zone in zones:
        if at_or_below(name, zone['origin']):
            depth = label_count(zone['origin'])
            if depth > best_depth:
                best_depth = depth
                best = zone
    return best


def select_source(current, zone, wildcard_mode):
    """Return the record source name for current inside zone, or None."""
    existing = zone['existing']
    if current in existing:
        return current
    if wildcard_mode == 'off':
        return None
    # closest encloser: longest existing ancestor of current
    encloser = None
    cursor = parent_name(current)
    while True:
        if cursor in existing:
            encloser = cursor
            break
        if cursor == zone['origin']:
            break
        cursor = parent_name(cursor)
    if encloser is None:
        return None
    if wildcard_mode == 'one-label':
        if label_count(current) != label_count(encloser) + 1:
            return None
    wildcard = name_of_labels(['*'] + labels_of(encloser))
    if wildcard in existing:
        return wildcard
    return None


def resolve(qname, qtype, profile, zones):
    """Execute the frozen local resolution model."""
    wildcard_mode = profile['wildcard']
    cname_mode = profile['cname']
    max_aliases = profile['max_aliases']
    seen = set()
    trace = []
    answer = []
    current = qname
    followed = 0
    while True:
        trace.append(current)
        if current in seen:
            return ('SERVFAIL', 'LOOP', current, answer, trace)
        seen.add(current)
        zone = select_zone(current, zones)
        if zone is None:
            if followed == 0:
                return ('REFUSED', 'OUTSIDE', current, answer, trace)
            return ('NOERROR', 'EXTERNAL', current, answer, trace)
        source = select_source(current, zone, wildcard_mode)
        if source is None:
            return ('NXDOMAIN', 'NXDOMAIN', current, answer, trace)
        types = zone['records'].get(source, {})
        cnames = types.get('CNAME')
        if qtype == 'CNAME':
            if cnames:
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': cnames[0]})
                return ('NOERROR', 'ANSWER', current, answer, trace)
            return ('NOERROR', 'NODATA', current, answer, trace)
        if cnames:
            if cname_mode == 'stop':
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': cnames[0]})
                return ('NOERROR', 'CNAME_STOP', current, answer, trace)
            if followed >= max_aliases:
                return ('SERVFAIL', 'LIMIT', current, answer, trace)
            answer.append({'owner': current, 'type': 'CNAME',
                           'data': cnames[0]})
            followed += 1
            current = cnames[0]
            continue
        rrset = types.get(qtype)
        if rrset:
            for data in rrset:
                answer.append({'owner': current, 'type': qtype, 'data': data})
            return ('NOERROR', 'ANSWER', current, answer, trace)
        return ('NOERROR', 'NODATA', current, answer, trace)


# ---------------------------------------------------------------- analysis

def compute_runs(queries, profiles, zones):
    runs = []
    projections = {}
    for query in sorted(queries, key=lambda item: item['id']):
        for profile in sorted(profiles, key=lambda item: item['id']):
            rcode, termination, final_name, answer, trace = resolve(
                query['name'], query['type'], profile, zones)
            runs.append({
                'query': query['id'],
                'profile': profile['id'],
                'rcode': rcode,
                'termination': termination,
                'final_name': final_name,
                'answer': answer,
                'trace': trace,
            })
            projections[(query['id'], profile['id'])] = (
                rcode,
                frozenset((item['owner'], item['type'], item['data'])
                          for item in answer),
            )
    return runs, projections


def compute_audits(observations, projections):
    audits = []
    for observation in sorted(observations, key=lambda item: item['id']):
        result = observation['result']
        if result['status'] == 'timeout':
            audits.append({'id': observation['id'], 'verdict': 'unobserved',
                           'different': []})
            continue
        observed_rcode = result['rcode']
        observed = frozenset(result['answer'])
        run_rcode, run_answer = projections[(observation['query'],
                                            observation['profile'])]
        different = []
        if observed_rcode != run_rcode:
            different.append('rcode')
        if observed != run_answer:
            different.append('answer')
        audits.append({
            'id': observation['id'],
            'verdict': 'match' if not different else 'divergence',
            'different': different,
        })
    return audits


def compute_diagnostic(queries, profiles, projections):
    query_ids = sorted(query['id'] for query in queries)
    profile_ids = sorted(profile['id'] for profile in profiles)
    costs = {query['id']: query['cost'] for query in queries}

    signatures = {}
    for pid in profile_ids:
        signatures[pid] = tuple(projections[(qid, pid)] for qid in query_ids)

    grouped = {}
    for pid in profile_ids:
        grouped.setdefault(signatures[pid], []).append(pid)
    classes = sorted(sorted(members) for members in grouped.values())

    pairs = []
    for index, first in enumerate(profile_ids):
        for second in profile_ids[index + 1:]:
            if signatures[first] != signatures[second]:
                pairs.append((first, second))

    if not pairs:
        return classes, [], 0, 0

    covers = []
    for qid in query_ids:
        mask = 0
        for index, (first, second) in enumerate(pairs):
            if projections[(qid, first)] != projections[(qid, second)]:
                mask |= 1 << index
        if mask:
            covers.append((mask, costs[qid], qid))

    # identical coverage: only the cheapest instance can ever be useful
    best_for_mask = {}
    for mask, cost, qid in covers:
        current = best_for_mask.get(mask)
        if current is None or (cost, qid) < (current[0], current[1]):
            best_for_mask[mask] = (cost, qid)
    items = [(mask, cost, qid)
             for mask, (cost, qid) in sorted(best_for_mask.items())]

    full = (1 << len(pairs)) - 1
    count_elements = len(pairs)
    elem_items = [[] for _ in range(count_elements)]
    conflict = [0] * count_elements
    for index, (mask, _cost, _qid) in enumerate(items):
        for element in range(count_elements):
            if (mask >> element) & 1:
                elem_items[element].append(index)
                conflict[element] |= mask
    elem_min_cost = []
    for element in range(count_elements):
        options = elem_items[element]
        elem_min_cost.append(min(items[index][1] for index in options))

    best_cost = None
    best_count = None
    best_choice = None
    seen = {}

    def packing_bound(covered):
        uncovered = [element for element in range(count_elements)
                     if not ((covered >> element) & 1)]
        uncovered.sort(key=lambda element: -elem_min_cost[element])
        picked = []
        total = 0
        for element in uncovered:
            if all(not ((conflict[element] >> other) & 1) for other in picked):
                picked.append(element)
                total += elem_min_cost[element]
        return total

    def search(covered, cost, count, chosen, banned):
        nonlocal best_cost, best_count, best_choice
        if covered == full:
            if best_cost is None or (cost, count) < (best_cost, best_count):
                best_cost = cost
                best_count = count
                best_choice = list(chosen)
            return
        previous = seen.get(covered)
        if previous is not None and (cost, count) >= previous:
            return
        seen[covered] = (cost, count)
        bound = packing_bound(covered)
        if best_cost is not None:
            if cost + bound > best_cost:
                return
            if cost + bound == best_cost and count + 1 >= best_count:
                return
        # pick the most constrained uncovered element
        target = None
        options = None
        for element in range(count_elements):
            if (covered >> element) & 1:
                continue
            available = [index for index in elem_items[element]
                         if index not in banned]
            if not available:
                continue
            if options is None or len(available) < len(options):
                target = element
                options = available
        if options is None:
            return
        options.sort(key=lambda index: (items[index][1], items[index][2]))
        for index in options:
            mask, cost_of, _qid = items[index]
            chosen.append(_qid)
            search(covered | mask, cost + cost_of, count + 1, chosen,
                   banned | {index})
            chosen.pop()
            banned = banned | {index}

    search(0, 0, 0, [], frozenset())
    if best_choice is None:
        # Should not happen: every distinguishing pair is covered by some
        # candidate query, so the full cover always exists.
        best_choice = []
    basis = sorted(best_choice)
    total_cost = sum(costs[qid] for qid in basis)
    return classes, basis, total_cost, len(basis)


def analyze(raw):
    document = parse_document(raw)
    require_keys(document, ('zones', 'profiles', 'queries', 'observations'))
    zones = parse_zones(document['zones'])
    profiles = parse_profiles(document['profiles'])
    queries = parse_queries(document['queries'])
    query_ids = set(query['id'] for query in queries)
    profile_ids = set(profile['id'] for profile in profiles)
    observations = parse_observations(document['observations'], query_ids,
                                      profile_ids)
    runs, projections = compute_runs(queries, profiles, zones)
    audits = compute_audits(observations, projections)
    equivalence, basis, cost, count = compute_diagnostic(queries, profiles,
                                                         projections)
    return {
        'runs': runs,
        'audits': audits,
        'diagnostic': {
            'equivalence': equivalence,
            'basis': basis,
            'cost': cost,
            'count': count,
        },
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        result = analyze(raw)
    except Invalid:
        result = {'error': 'invalid-input'}
    except Exception:
        result = {'error': 'invalid-input'}
    sys.stdout.write(json.dumps(result, separators=(',', ':')) + '\n')
    return 0


if __name__ == '__main__':
    sys.exit(main())
